// Parse XML RSS feed and extract items from last 24 hours
const items = [];
const cutoff = new Date(Date.now() - 24 * 60 * 60 * 1000);

for (const input of $input.all()) {
  const body = input.json.data || '';
  const source = input.json.url || 'Unknown';

  // Extract <item> blocks
  const itemRegex = /<item[^>]*>([\s\S]*?)<\/item>/gi;
  let match;
  while ((match = itemRegex.exec(body)) !== null) {
    const block = match[1];
    const get = (tag) => {
      const r = new RegExp(`<${tag}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\/${tag}>|<${tag}[^>]*>([\\s\\S]*?)<\/${tag}>`, 'i');
      const m = r.exec(block);
      return m ? (m[1] || m[2] || '').trim() : '';
    };

    const title = get('title');
    const link = get('link');
    const pubDate = get('pubDate');
    const description = get('description').replace(/<[^>]+>/g, '').substring(0, 300);
    const category = get('category');

    if (!title) continue;

    let published = pubDate ? new Date(pubDate) : null;
    if (published && published < cutoff) continue; // skip items older than 24h

    items.push({
      json: {
        title,
        link,
        pubDate: published ? published.toISOString() : 'Unknown',
        description,
        category,
        source
      }
    });
  }
}

// Deduplicate by title
const seen = new Set();
const unique = items.filter(i => {
  if (seen.has(i.json.title)) return false;
  seen.add(i.json.title);
  return true;
});

if (unique.length === 0) {
  return [{ json: { noItems: true, message: 'No new M365 updates in the last 24 hours.' } }];
}

return unique;

// Aggregate all items into one object for AI analysis
const allItems = $input.all().map(i => i.json);

const formatted = allItems.map((item, idx) => 
  `[${idx + 1}] ${item.title}\nSource: ${item.source}\nDate: ${item.pubDate}\nSummary: ${item.description}\nURL: ${item.link}`
).join('\n\n---\n\n');

return [{
  json: {
    itemCount: allItems.length,
    formattedItems: formatted,
    rawItems: allItems
  }
}];
